SELECT replaceRegexpOne(replaceRegexpOne(toString(properties.$current_url),'^https?://[^/]+',''),'[?#].*$','') AS Page, uniqExact(person_id) AS Visitors, count() AS Pageviews FROM events WHERE event = '$pageview' AND (properties.surface IS NULL OR properties.surface = 'web') AND (properties.environment IS NULL OR properties.environment = 'production') AND match(toString(properties.$current_url), '^https://(www[.])?ypr[.]app(/|$)') AND {filters} GROUP BY Page ORDER BY Visitors DESC LIMIT 30
